export type StopRecordingResultStatus =
  (typeof StopRecordingResultStatus)[keyof typeof StopRecordingResultStatus];

export const StopRecordingResultStatus = {
  completed: "completed",
  collision: "collision",
} as const;

/**
 * Status of the approval submission, when one was created. Always
`pending` immediately after submit. Null in `save` mode.

 * @nullable
 */
export type StopRecordingResultSubmissionStatus =
  | (typeof StopRecordingResultSubmissionStatus)[keyof typeof StopRecordingResultSubmissionStatus]
  | null;

export const StopRecordingResultSubmissionStatus = {
  pending: "pending",
  approved: "approved",
  rejected: "rejected",
} as const;

/**
 * On success the response carries `status: "completed"` plus the list of
generated files and a summary. When the requested test method name
already exists in the target class, the server instead returns
`status: "collision"` along with the colliding name, a suggested
unique name, and the target class so the UI can prompt the user.

 */
export interface StopRecordingResult {
  status: StopRecordingResultStatus;
  /** @nullable */
  generatedFiles?: GeneratedFile[] | null;
  /** @nullable */
  summary?: string | null;
  /** @nullable */
  methodName?: string | null;
  /** @nullable */
  suggestedName?: string | null;
  /** @nullable */
  targetClass?: string | null;
  /**
   * Project-relative path to a `.bak` file that captured the
previous setup-hook body when this recording overwrote a
non-default hook. Null for test-method recordings, brand-new
hooks, or hooks that only held the default stub.

   * @nullable
   */
  hookBackupPath?: string | null;
  /**
   * ID of the approval submission created by `submit-for-approval`
mode. Null when the stop ran in plain `save` mode.

   * @nullable
   */
  submissionId?: string | null;
  /**
   * Status of the approval submission, when one was created. Always
`pending` immediately after submit. Null in `save` mode.

   * @nullable
   */
  submissionStatus?: StopRecordingResultSubmissionStatus;
}

export interface ReplayableHookInfo {
  /** True when the hook's body has been customised (i.e. NOT the default `return Task.CompletedTask;` stub). */
  hasCustomBody: boolean;
  /** True when AutoScriba has stored the underlying RecordedAction[] for this hook and can replay it before a new [Test] recording. */
  hasStoredActions: boolean;
}

export interface ReplayableHooksResult {
  beforeEach: ReplayableHookInfo;
  oneTimeSetup: ReplayableHookInfo;
}

