/**
 * The four languages memento generates tests for. The server picks
a parser per language and the corresponding CLI runner when
executing a selection-based run.

 */
export type TestLanguage = (typeof TestLanguage)[keyof typeof TestLanguage];

export const TestLanguage = {
  csharp: "csharp",
  python: "python",
  nodejs: "nodejs",
  java: "java",
} as const;

/**
 * Test classification. A method is **e2e** by default if its file
lives under an `e2e/` folder OR carries an e2e tag/attribute
(`[Category("E2E")]`, `@pytest.mark.e2e`,
`test.describe("@e2e", …)`, JUnit `@Tag("e2e")`); **api** if
under `api/` or tagged `api`; **unit** otherwise. Folder
convention is the default classifier; an explicit tag or
attribute on the method (or its enclosing class) overrides
folder placement.

 */
export type TestKind = (typeof TestKind)[keyof typeof TestKind];

export const TestKind = {
  e2e: "e2e",
  unit: "unit",
  api: "api",
} as const;

/**
 * Rolled-up counts of test methods inside this subtree.
 */
export interface TestTotals {
  /** @minimum 0 */
  e2e: number;
  /** @minimum 0 */
  unit: number;
  /** @minimum 0 */
  api: number;
  /** @minimum 0 */
  all: number;
}

export type DiscoveredTestMethodType =
  (typeof DiscoveredTestMethodType)[keyof typeof DiscoveredTestMethodType];

export const DiscoveredTestMethodType = {
  method: "method",
} as const;

/**
 * A single discovered test method (a leaf in the discovery tree).

 */
export interface DiscoveredTestMethod {
  type: DiscoveredTestMethodType;
  /** Stable, fully-qualified test ID — opaque to the UI, but the
shape is contract-stable per language so the server can
translate it back to the right CLI invocation:

  - **csharp** — `Namespace.ClassName.MethodName`
    (e.g. `Memento.Tests.Login.LoginSuite.HappyPath`).
    Parameterized `[TestCase]`s collapse into the parent
    method id; running it runs every case.
  - **python** — pytest node id:
    `relative/path/to/file.py::ClassName::test_method`
    (`ClassName::` omitted for module-level functions).
  - **nodejs** — Playwright human-readable id:
    `relative/path/to/file.spec.ts > describe title > test title`
    (` > ` separator). Nested describes chain with the same
    separator. Used as the `--grep` regex source after
    escaping.
  - **java** — `com.pkg.ClassName#methodName`.
 */
  id: string;
  /** The method's display name (last segment of `id`). */
  name: string;
  kind: TestKind;
  language: TestLanguage;
}

export type DiscoveredTestFileType =
  (typeof DiscoveredTestFileType)[keyof typeof DiscoveredTestFileType];

export const DiscoveredTestFileType = {
  file: "file",
} as const;

/**
 * A test file containing one or more discovered test methods.

 */
export interface DiscoveredTestFile {
  type: DiscoveredTestFileType;
  name: string;
  /** Project-relative POSIX path to the file. */
  path: string;
  language: TestLanguage;
  totals: TestTotals;
  methods: DiscoveredTestMethod[];
}

export type DiscoveredTestFolderType =
  (typeof DiscoveredTestFolderType)[keyof typeof DiscoveredTestFolderType];

export const DiscoveredTestFolderType = {
  folder: "folder",
} as const;

/**
 * A folder in the discovery tree. Holds rolled-up test counts and
nested folder/file children.

 */
export interface DiscoveredTestFolder {
  type: DiscoveredTestFolderType;
  name: string;
  /** Project-relative POSIX path to the folder. */
  path: string;
  totals: TestTotals;
  children: DiscoveredTestNode[];
}

/**
 * Either a folder (with rolled-up totals and child nodes) or a
file (with the test methods inside it). Children of a folder
are returned in deterministic order: folders first, then files,
each block sorted alphabetically by `name`.

 */
export type DiscoveredTestNode = DiscoveredTestFolder | DiscoveredTestFile;

/**
 * Top-level discovery payload for the currently loaded project.
`root` is the project root folder and always carries the full
rolled-up totals.

 */
export interface TestDiscoveryResponse {
  projectName: string;
  slnPath: string;
  root: DiscoveredTestFolder;
}

/**
 * Request body for a selection-based run. `testIds` must be a
non-empty list of ids returned verbatim from a prior discovery
response. The server groups them by language and dispatches
each group to the right CLI runner.

 */
export interface RunBySelectionRequest {
  /** @minItems 1 */
  testIds: string[];
}

export type SelectionRunGroupStatus =
  (typeof SelectionRunGroupStatus)[keyof typeof SelectionRunGroupStatus];

export const SelectionRunGroupStatus = {
  running: "running",
  passed: "passed",
  failed: "failed",
  error: "error",
} as const;

/**
 * Per-language entry in a selection-based run. The body is a flat
record carrying the standard `InternalTestRun` fields plus the
`language`, the `testIds` that were dispatched, and the
captured `stdout` / `stderr` from the CLI runner so the UI can
show real compile errors and assertion traces inline.

 */
export interface SelectionRunGroup {
  id: string;
  suiteKey: string;
  suiteName: string;
  startedAt: string;
  finishedAt: string | null;
  status: SelectionRunGroupStatus;
  exitCode: number | null;
  errorMessage: string | null;
  startedBy: InternalTestRunStartedBy;
  language: TestLanguage;
  testIds: string[];
  stdout: string;
  stderr: string;
}

export type SelectionRunDetailStatus =
  (typeof SelectionRunDetailStatus)[keyof typeof SelectionRunDetailStatus];

export const SelectionRunDetailStatus = {
  running: "running",
  passed: "passed",
  failed: "failed",
  error: "error",
} as const;

/**
 * Snapshot of a single dispatched selection run, returned by
`GET /projects/{projectId}/runs/by-selection/{runId}`. Polled by
the run-detail UI until `finishedAt` flips from null to a
timestamp; `stdout` / `stderr` carry the captured CLI output
(each capped at 256 KB) so SDETs can read compile errors and
assertion traces without digging through server logs.

 */
export interface SelectionRunDetail {
  id: string;
  suiteKey: string;
  suiteName: string;
  startedAt: string;
  finishedAt: string | null;
  status: SelectionRunDetailStatus;
  exitCode: number | null;
  errorMessage: string | null;
  startedBy: InternalTestRunStartedBy;
  projectKey: string;
  stdout: string;
  stderr: string;
}

/**
 * Response payload for a selection-based run — a list of
per-language run entries, each carrying the standard
`InternalTestRun` record so the UI reuses the existing
run-detail surface.

 */
export interface RunBySelectionResponse {
  runs: SelectionRunGroup[];
}

